    "materiContent": {
      "text": "Raka menempel jadwal hari Minggu di dinding kamarnya.\n\nJam | Kegiatan\n\n06.00 | Bangun tidur dan mandi\n\n07.00 | Sarapan bersama keluarga\n\n08.30 | Kerja bakti di lingkungan RT\n\n10.00 | Bermain di rumah Doni\n\n12.00 | Makan siang\n\nRaka melihat jam dinding. Jarum pendek ada di antara angka 8 dan 9, sedangkan jarum panjang menunjuk angka 6. “Ayo, waktunya kerja bakti!” ajak Ayah.",
      "image": "/covers/cover-k2-b7.jpg",
      "audioUrl": "",
      "points": [
        {
          "id": "lp-k2b7-1",
          "title": "* Jarum pendek",
          "desc": "* Jarum pendek menunjukkan jam, sedangkan jarum panjang menunjukkan menit."
        },
        {
          "id": "lp-k2b7-2",
          "title": "Jam tepat",
          "desc": "jarum panjang di angka 12 (contoh: 07.00)."
        },
        {
          "id": "lp-k2b7-3",
          "title": "Setengah jam",
          "desc": "jarum panjang di angka 6 dan jarum pendek di antara dua angka (08.30 dibaca \"setengah sembilan\" karena menuju pukul 9)."
        },
        {
          "id": "lp-k2b7-4",
          "title": "Satuan waktu",
          "desc": "1 jam = 60 menit; setengah jam = 30 menit."
        },
        {
          "id": "lp-k2b7-5",
          "title": "Membaca jadwal dilakukan",
          "desc": "Membaca jadwal dilakukan dengan mencari baris jam yang ditanyakan lalu melihat kegiatan di sebelahnya."
        },
        {
          "id": "lp-k2b7-6",
          "title": "Contoh soal cerita",
          "desc": "Dari bangun pukul 06.00 sampai sarapan pukul 07.00 lamanya adalah 1 jam."
        }
      ]
    },
