    "description": "Belajar menemukan informasi penting dalam teks informasi serta menjumlahkan dan mengurangkan bilangan sampai 1.000 dengan teknik menyimpan dan meminjam.",
    "duration": "± 5-7 menit",
    "activityType": "Materi + Video + Kuis",
