    "materiContent": {
      "text": "Pak Darto adalah petani padi di desa kami. Ia membuat pupuk cair sendiri. Petugas penyuluh pertanian mengajarinya mencampur 1 liter cairan pupuk dengan 4 liter air. Jika campurannya terlalu pekat, daun padi bisa layu. Jika terlalu encer, pupuk kurang bermanfaat.\n\nPak Darto juga perlu membeli kompos. Toko Subur menjual 5 kg kompos seharga Rp60.000. Toko Makmur menjual 3 kg kompos seharga Rp39.000. Tetangganya berkata, “Toko Makmur pasti lebih murah karena harganya di bawah Rp40.000.” Pak Darto memilih menghitung dulu sebelum membeli.",
      "image": "/covers/cover-k6-b1.jpg",
      "audioUrl": "",
      "points": [
        {
          "id": "lp-k6b1-1",
          "title": "* Rasio adalah",
          "desc": "* Rasio adalah perbandingan dua jumlah (cairan pupuk : air = 1 : 4). Urutan rasio sangat penting dan dapat disederhanakan dengan membagi kedua bilangan dengan FPB-nya."
        },
        {
          "id": "lp-k6b1-2",
          "title": "Proporsi",
          "desc": "kesamaan dua rasio (1 : 4 = 2 : 8 = 3 : 12)."
        },
        {
          "id": "lp-k6b1-3",
          "title": "Rasio satuan menghitung",
          "desc": "Rasio satuan menghitung nilai per 1 satuan untuk membandingkan secara adil: Toko Subur = Rp60.000 : 5 = Rp12.000/kg; Toko Makmur = Rp39.000 : 3 = Rp13.000/kg. Jadi Toko Subur lebih murah."
        },
        {
          "id": "lp-k6b1-4",
          "title": "Fakta",
          "desc": "data yang dapat dibuktikan, sedangkan opini adalah pendapat atau dugaan (sering memakai kata pasti, sebaiknya, menurut saya) yang perlu diuji dengan data."
        },
        {
          "id": "lp-k6b1-5",
          "title": "Contoh soal cerita",
          "desc": "Untuk 3 liter cairan pupuk dengan rasio 1 : 4, dibutuhkan 4 x 3 = 12 liter air (total campuran 15 liter)."
        }
      ]
    },
